public void start() {
    this.mEditor.mDrawerLayout.setDrawerLockMode(1);
    this.mEditor.mFramesContainer.setVisibility(8);
    this.mEditor.mControls.setVisibility(8);
    this.mEditor.mFragmentCont.setVisibility(8);
    TempState.sNoOnion = true;
    StickmanView stickmanView = this.mEditor.mStickmanView;
    stickmanView.mStickmanPresenter.getDrawingConfig().mUseHandlers = false;
    stickmanView.mStickmanPresenter.navigablePresenter().mAllowSceneMovements = false;
    stickmanView.updateViewportProps();
    stickmanView.invalidate();
    MainEditor mainEditor = this.mEditor;
    UIUtils.niceToast(mainEditor, mainEditor.getString(R.string.move_me), 1, UIUtils.TOAST_KIND.INFO);
    EventBus.getDefault().register(this);
}
